"""Canonical ScanResult used by the reporter golden-snapshot tests (#54).

The fixture is intentionally small but covers every severity, every reporter
field, and a handful of representative rules. All values are deterministic —
no timestamps, no per-run state — so the rendered output is byte-stable
across runs and platforms.

Secrets here are clearly fake (``AKIAIOSFODNN7EXAMPLE`` is the canonical AWS
documentation placeholder).
"""

from __future__ import annotations

from vibeguard.models import Confidence, Finding, ScanResult, Severity


def build_canonical_result() -> ScanResult:
    """Return a deterministic ScanResult covering all severities."""
    findings = [
        Finding(
            id="SEC-AWSACCESSKEY",
            rule="secrets",
            title="AWS Access Key ID detected",
            description=(
                "A likely AWS Access Key ID was found in `src/config.py` at line 9. "
                "Committed secrets can be exploited by anyone with repo access."
            ),
            severity=Severity.CRITICAL,
            path="src/config.py",
            line=9,
            evidence='AWS_KEY = "AKIA****LE"',
            recommendation=(
                "Remove the secret from source code. Rotate it immediately. "
                "Use environment variables or a secrets manager instead."
            ),
            tags=["secrets", "aws-access-key"],
            confidence=Confidence.HIGH,
        ),
        Finding(
            id="MAP-DIST",
            rule="sourcemaps",
            title="Source map file in publish directory",
            description=(
                "Source map `dist/app.js.map` is in a publish directory. "
                "Source maps reveal original source code if shipped to production."
            ),
            severity=Severity.HIGH,
            path="dist/app.js.map",
            line=None,
            evidence=None,
            recommendation=(
                "Exclude `*.map` files from the published bundle, or strip the "
                "`sourceMappingURL` reference before publishing."
            ),
            tags=["sourcemaps", "publish-leak"],
            confidence=Confidence.HIGH,
        ),
        Finding(
            id="RISK-EVALEXEC",
            rule="risky_diff",
            title="Risk-sensitive area changed: eval() or exec() usage",
            description=(
                "`src/server.js` line 24 touches a risk-sensitive area (eval/exec). "
                "This is not a confirmed vulnerability — human review is recommended."
            ),
            severity=Severity.MEDIUM,
            path="src/server.js",
            line=24,
            evidence="const value = eval(userInput);",
            recommendation=(
                "Replace eval/exec with safer alternatives (JSON.parse, dispatch tables, "
                "explicit validation)."
            ),
            tags=["risky_diff", "eval-exec"],
            confidence=Confidence.MEDIUM,
        ),
        Finding(
            id="TEST-MISSING",
            rule="tests",
            title="Source changes without test changes",
            description=(
                "3 source file(s) changed but no test files were modified. "
                "Changed files include: `src/auth.py`, `src/server.py`, `src/db.py`"
            ),
            severity=Severity.LOW,
            path="src/auth.py",
            line=None,
            evidence=None,
            recommendation=(
                "Add or update tests to cover the changed code. Untested AI-generated "
                "code is a common source of bugs and regressions."
            ),
            tags=["tests", "coverage"],
            confidence=Confidence.MEDIUM,
        ),
        Finding(
            id="AI-AIGENERATED",
            rule="ai_footprints",
            title="AI-generated code comment",
            description=(
                "`src/utils.js` line 1 contains a comment marking the file as "
                "AI-generated. Useful as provenance; informational only."
            ),
            severity=Severity.INFO,
            path="src/utils.js",
            line=1,
            evidence="// generated by ChatGPT",
            recommendation=(
                "Review AI-generated code for correctness and security implications "
                "before merging."
            ),
            tags=["ai-footprint", "ai-generated"],
            confidence=Confidence.MEDIUM,
        ),
    ]
    return ScanResult(
        findings=findings,
        scanned_files=12,
        changed_files=4,
        scan_path="/repo",
        policy="balanced",
        errors=[],
    )
